style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com") {
/* Global text and icon color */
    * {
        color: #ffffff !important;
        fill: #ffffff !important; /* For SVG icons */
    }

    /* Background for core areas */
    body, html, ytd-app, ytd-page-manager,
    ytd-watch-flexy, ytd-masthead, ytd-comments,
    ytd-watch-metadata, ytd-guide-renderer,
    ytd-video-primary-info-renderer, ytd-video-secondary-info-renderer {
        background-color: #000000 !important;
    }

    /* Header & sidebar */
    ytd-masthead, #container.ytd-masthead,
    ytd-guide-section-renderer {
        background-color: #0a0a0a !important;
        border-bottom: 1px solid #222 !important;
    }

    /* Search bar background and input */
    ytd-searchbox {
        background-color: #000000 !important;
        border: 1px solid #333 !important;
    }

    input#search {
        background-color: #000000 !important;
        color: #ffffff !important;
        border: none !important;
    }

    /* Ensure placeholder text is also white */
    input#search::placeholder {
        color: #bbbbbb !important;
        opacity: 1 !important;
    }

    /* Menus and dropdowns */
    tp-yt-paper-listbox, ytd-popup-container {
        background-color: #121212 !important;
    }

    /* Thumbnail area backgrounds */
    ytd-thumbnail {
        background-color: #111111 !important;
    }

    /* Button and icon tinting */
    yt-icon, yt-icon-button, tp-yt-paper-button, ytd-toggle-button-renderer {
        color: #ffffff !important;
        fill: #ffffff !important;
    }

    /* Scrollbars for aesthetics */
    ::-webkit-scrollbar {
        width: 8px;
    }
    ::-webkit-scrollbar-track {
        background: #000;
    }
    ::-webkit-scrollbar-thumb {
        background: #555;
    }
}
